examples.code:
history = {"A": [(0, 0), (30, 1), (60, 5)]}  # (시각, 누적 신고 수)
orders = [("A", 20, 1), ("A", 50, 0)]       # (계정, 주문 시각, 사기였나)

def as_of(acct, t):
    v = 0
    for ts, val in history[acct]:
        if ts <= t:
            v = val
    return v

latest = history["A"][-1][1]
for acct, t, label in orders:
    print(f"주문 t={t}: 그때 값={as_of(acct, t)}  최신 값={latest}  정답={label}")
# 주문 t=20: 그때 값=0  최신 값=5  정답=1
# 주문 t=50: 그때 값=1  최신 값=5  정답=0
